window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-2f363e2b27e6532a"]={"versions": [{"id": "FIG-2f363e2b27e6532a", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Screenshot einer MATLAB/Simulink-Blockmaske („Function Block Parameters: SenderReceiverComSpec“). Das Dialogfenster dient der Konfiguration von senderseitigen Kommunikationsspezifikationen (<code>DataSenderComSpec</code>) für Schnittstellen im Rahmen des AUTOSAR-Simulink-Workflows und der Modellierung von Software-Komponenten (SWC).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Fenster zeigt den Reiter <strong>ComSpec</strong> innerhalb der Blockmaske <code>DataSenderComSpec (mask)</code> neben den weiteren Reitern <code>Annotations</code> und <code>Extras</code>. Im Reiter <code>ComSpec</code> sind folgende Steuerelemente vorhanden:</p>\n<ul class=\"fig-list\"><li>Checkbox <code>Acknowledge</code> (aktiviert / gesetzt)\n</li><li>Checkbox <code>canInvalidate</code> (aktiviert / gesetzt)\n</li><li>Text-/Eingabefeld <code>Initial value</code> mit dem eingetragenen Wert <code>6.0</code>\n</li></ul>\n<p class=\"fig-p\">Am unteren Fensterrand befinden sich die Standard-Schaltflächen <code>OK</code>, <code>Cancel</code>, <code>Help</code> sowie die inaktive Schaltfläche <code>Apply</code>. Die Maskenbeschreibung erläutert den Zweck der Kapselung von Annotations und Communication Specifications zur Beeinflussung der SWC-Beschreibung und der für die Codegenerierung der Runnables erforderlichen APIs.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statischer Konfigurationsdialog zur Entwurfszeit in Simulink. Die getroffenen Einstellungen legen Eigenschaften der Datenübertragung für Sende-Ports fest: Bestätigungsanforderung (<code>Acknowledge</code>), Unterstützung der Daten-Invalidierung (<code>canInvalidate</code>) sowie Vorbelegung mit einem Initialwert (<code>Initial value = 6.0</code>) vor dem ersten Sendevorgang.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Konfiguration wirkt sich direkt auf das AUTOSAR-XML-Modell (SWC-Description) und die generierten RTE-Schnittstellen bzw. APIs des Runnables aus. Sie definiert die Kommunikationsattribute der <code>DataSenderComSpec</code> für Sender-Receiver-Kommunikation.</p>"}, {"id": "FIG-6066290c7504b15c", "releases": ["R3.0.7", "R3.1.5", "R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Screenshot einer MATLAB/Simulink-Blockmaske („Function Block Parameters: SenderReceiverComSpec“). Das Dialogfenster dient der Konfiguration von senderseitigen Kommunikationsspezifikationen (<code>DataSenderComSpec</code>) für Schnittstellen im Rahmen des AUTOSAR-Simulink-Workflows und der Modellierung von Software-Komponenten (SWC).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Fenster zeigt den Reiter <strong>ComSpec</strong> innerhalb der Blockmaske <code>DataSenderComSpec (mask)</code> neben den weiteren Reitern <code>Annotations</code> und <code>Extras</code>. Im Reiter <code>ComSpec</code> sind folgende Steuerelemente vorhanden:</p>\n<ul class=\"fig-list\"><li>Checkbox <code>Acknowledge</code> (aktiviert / gesetzt)\n</li><li>Checkbox <code>canInvalidate</code> (aktiviert / gesetzt)\n</li><li>Text-/Eingabefeld <code>Initial value</code> mit dem eingetragenen Wert <code>6.0</code>\n</li></ul>\n<p class=\"fig-p\">Am unteren Fensterrand befinden sich die Standard-Schaltflächen <code>OK</code>, <code>Cancel</code>, <code>Help</code> sowie die inaktive Schaltfläche <code>Apply</code>. Die Maskenbeschreibung erläutert den Zweck der Kapselung von Annotations und Communication Specifications zur Beeinflussung der SWC-Beschreibung und der für die Codegenerierung der Runnables erforderlichen APIs.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statischer Konfigurationsdialog zur Entwurfszeit in Simulink. Die getroffenen Einstellungen legen Eigenschaften der Datenübertragung für Sende-Ports fest: Bestätigungsanforderung (<code>Acknowledge</code>), Unterstützung der Daten-Invalidierung (<code>canInvalidate</code>) sowie Vorbelegung mit einem Initialwert (<code>Initial value = 6.0</code>) vor dem ersten Sendevorgang.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Konfiguration wirkt sich direkt auf das AUTOSAR-XML-Modell (SWC-Description) und die generierten RTE-Schnittstellen bzw. APIs des Runnables aus. Sie definiert die Kommunikationsattribute der <code>DataSenderComSpec</code> für Sender-Receiver-Kommunikation.</p>"}], "trans": [{"from": "FIG-2f363e2b27e6532a", "to": "FIG-6066290c7504b15c", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
